{
  "contract": "TRYPTO",
  "closure": {
    "site_function": "take_marketing",
    "site_call": ".call",
    "functions": [
      "take_marketing",
      "take_growth"
    ],
    "justification": "take_marketing can re-enter via .call and affect _ethBal; take_growth similarly affects _ethBal and growth_balance."
  },
  "protocol": {
    "during_phase": "exposed",
    "allowed_callbacks": [
      "take_marketing",
      "take_growth"
    ],
    "nesting_bound": {
      "take_marketing": 1,
      "take_growth": 1
    }
  },
  "phases": {
    "function": "take_marketing",
    "pre": {
      "name": "pre",
      "from_marker": "initial state",
      "to_marker": "before .call"
    },
    "exposed": {
      "name": "exposed",
      "from_marker": "after .call",
      "to_marker": "before state restore"
    },
    "post": {
      "name": "post",
      "from_marker": "after state restore",
      "to_marker": "final state"
    },
    "linearization_point": "before .call"
  },
  "ghost_state": [
    {
      "name": "inFlight",
      "sol_type": "uint256",
      "meaning": "tracks the amount in transition during .call",
      "backed_by_storage": false
    }
  ],
  "exposure_invariant": {
    "formula": "marketing_balance + growth_balance + inFlight <= _ethBal",
    "stable_formula": "marketing_balance + growth_balance <= _ethBal",
    "kind": "bounded"
  },
  "composition": {
    "target_property": "marketing_balance + growth_balance <= _ethBal",
    "rule": "use bounded drift to ensure balance conditions hold across reentrancy"
  }
}
